#!/bin/sh
# Rebuild public/airc-crypto.js from pinned @noble releases. The output is
# checked in, so neither the server nor the browser needs a build step; run
# this only to bump a version, then review the diff and rerun the tests.
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/../.." && pwd)
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
cp "$HERE/airc-crypto-entry.mjs" "$WORK/"
cd "$WORK"
npm init -y >/dev/null
npm install --silent --ignore-scripts --no-audit --no-fund \
  @noble/curves@2.4.0 @noble/ciphers@2.4.0 @noble/hashes@2.4.0 esbuild@0.25.10
{
  echo "// Generated by scripts/vendor/build-airc-crypto.sh; do not edit."
  echo "// @noble/curves 2.4.0, @noble/ciphers 2.4.0, @noble/hashes 2.4.0 (MIT, Paul Miller)."
  npx esbuild airc-crypto-entry.mjs --bundle --format=iife --global-name=AircCrypto \
    --target=es2020 --minify --legal-comments=inline \
    --footer:js='if (typeof module === "object" && module.exports) { module.exports = AircCrypto; }'
} > "$ROOT/public/airc-crypto.js"
echo "wrote public/airc-crypto.js ($(wc -c < "$ROOT/public/airc-crypto.js") bytes)"
